#include <stdio.h>
#include <string.h>

#define MAX_N 100000

int main() {
    int N, K;
    scanf("%d %d", &N, &K);

    int A[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }

    int stack[MAX_N * 100]; // worst-case size
    int top = -1;
    int freq[100001] = {0}; // values up to 100000

    for (int i = 0; i < K; i++) {
        for (int j = 0; j < N; j++) {
            int x = A[j];
            if (top >= 0 && stack[top] == x) {
                // remove top
                freq[x]--;
                top--;
            } else {
                // add to stack
                top++;
                stack[top] = x;
                freq[x]++;
            }
        }
    }

    for (int i = 0; i <= top; i++) {
        printf("%d ", stack[i]);
    }
    printf("\n");

    return 0;
