    int a[100005];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    // Build the N*K sequence
    int seq[100005 * 10]; // result sequence
    int top = 0;

    // For each of the N*K elements
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < k; j++) {
            int x = a[i];
            // Check if x is in seq[0..top-1]
            int found = 0;
            for (int t = 0; t < top; t++) {
                if (seq[t] == x) { found = 1; break; }
            }
            if (found) {
                if (top > 0) top--;
            } else {
                seq[top++] = x;
            }
        }
    }

    printf("%d\n", top);
    for (int i = 0; i < top; i++) {
        printf("%d", seq[i]);
        if (i < top-1) printf(" ");
    }
    printf("\n");

    return 0;
