#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *A = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) scanf("%d", &A[i]);

    /* stack of current sequence */
    int *stack = (int *)malloc(sizeof(int) * N);
    int top = 0;

    /* position of value in stack, -1 if absent.
       In the original problem values are in [1, N]. */
    int *pos = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 0; i <= N; i++) pos[i] = -1;

    for (int i = 0; i < N; i++) {
        int x = A[i];
        if (pos[x] == -1) {
            pos[x] = top;
            stack[top++] = x;
        } else {
            int p = pos[x];
            while (top > p) {
                pos[stack[top - 1]] = -1;
                top--;
            }
        }
    }

    for (int i = 0; i < top; i++) {
        if (i) putchar(' ');
        printf("%d", stack[i]);
    }
    putchar('\n');

    free(A);
    free(stack);
    free(pos);
    return 0;
}

