import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        int[] A = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }

        Map<Integer, Integer> countMap = new HashMap<>();
        Deque<Integer> stack = new ArrayDeque<>();

        for (int i = 0; i < N * K; i++) {
            int x = A[i % N];
            countMap.put(x, countMap.getOrDefault(x, 0) + 1);
            stack.push(x);

            if (countMap.get(x) == K) {
                // Remove last K occurrences of x
                int removed = 0;
                while (removed < K) {
                    int top = stack.pop();
                    countMap.put(top, countMap.get(top) - 1);
                    if (countMap.get(top) == 0) {
                        countMap.remove(top);
                    }
                    removed++;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int val : stack) {
            sb.append(val).append(" ");
        }
        // Since we used push to stack, the order is reversed.
        // We built the stack with push, so popping gives reversed order.
        // Instead, iterate from bottom to top:
        List<Integer> list = new ArrayList<>(stack);
        Collections.reverse(list);
        for (int val : list) {
            sb.append(val).append(" ");
        }

        if (sb.length() > 0) {
            sb.setLength(sb.length() - 1);
        }
        System.out.println(sb.toString());
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int[] a = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) a[i] = Integer.parseInt(st.nextToken());

        Deque<Integer> stack = new ArrayDeque<>();
        Map<Integer, Integer> count = new HashMap<>();

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < K; j++) {
                int v = a[i];
                if (count.getOrDefault(v, 0) > 0) {
                    // delete last element
                    int last = stack.peekLast();
                    stack.pollLast();
                    count.merge(last, -1, Integer::sum);
                } else {
                    stack.addLast(v);
                    count.merge(v, 1, Integer::sum);
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int x : stack) sb.append(x).append("\n");
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int K = fs.nextInt();

        long[] A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        ArrayDeque<Long> stack = new ArrayDeque<>();
        HashSet<Long> inSeq = new HashSet<>();

        for (int i = 0; i < N; i++) {
            long x = A[i];
            if (!inSeq.contains(x)) {
                stack.addLast(x);
                inSeq.add(x);
            } else {
                while (!stack.isEmpty()) {
                    long v = stack.removeLast();
                    inSeq.remove(v);
                    if (v == x) break;
                }
            }
        }

        if (stack.isEmpty()) {
            System.out.println();
            return;
        }

        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (long v : stack) {
            if (!first) sb.append(' ');
            first = false;
            sb.append(v);
        }
        System.out.println(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
